import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({ baseURL: "http://localhost:8000" });
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

function ProfilePage() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) { navigate("/login"); return; }
    fetchProfile();
  }, [navigate]);

  const fetchProfile = async () => {
    setIsLoading(true);
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      } else {
        setMessage("Error loading profile information.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const goToEnhancedUpload = () => navigate("/upload");

  const LoadingSpinner = () => (
    <div className="loading-spinner"><div className="spinner"></div></div>
  );

  return (
    <div className="container-page">
      <div className="page-header">
        <div className="title">Employee Dashboard</div>
      </div>

      <div className="content-card">
        {isLoading ? (
          <div className="loading-container">
            <LoadingSpinner />
            <p>Loading profile...</p>
          </div>
        ) : profile ? (
          <div>
            <div className="profile-card">
              <div className="profile-avatar">
                {profile.name ? profile.name.charAt(0).toUpperCase() :
                 profile.username ? profile.username.charAt(0).toUpperCase() :
                 profile.email ? profile.email.charAt(0).toUpperCase() : '?'}
              </div>
              <div className="profile-details">
                {profile.name && (
                  <div className="profile-field"><label>Name:</label><span>{profile.name}</span></div>
                )}
                {profile.username && (
                  <div className="profile-field"><label>Username:</label><span>{profile.username}</span></div>
                )}
                {profile.email && (
                  <div className="profile-field"><label>Email:</label><span>{profile.email}</span></div>
                )}
                <div className="profile-field">
                  <label>Authentication Type:</label>
                  <span className={`auth-type ${profile.auth_type}`}>
                    {profile.auth_type === 'google' ? 'Google Account' : 'Regular Account'}
                  </span>
                </div>
                {profile.created_at && (
                  <div className="profile-field"><label>Member Since:</label><span>{new Date(profile.created_at).toLocaleDateString()}</span></div>
                )}
              </div>
            </div>

            <div className="hero-card">
              <div className="hero-title">AI-Powered Expense Management</div>
              <div className="hero-subtitle">Upload your receipts and bills for AI-powered processing with Gemini 2.0 Flash technology.</div>
              <button className="btn btn-primary hero-button" onClick={goToEnhancedUpload}>
                🚀 Upload & Process Bill
              </button>
            </div>
          </div>
        ) : (
          <div className="error-container">
            <p>Unable to load profile information.</p>
            <button className="btn btn-primary" onClick={fetchProfile}>Try Again</button>
          </div>
        )}
      </div>

      {message && <div className="message error">{message}</div>}
    </div>
  );
}

export default ProfilePage;
